{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "NHC, a cytidine analogue with an additional polar modification, is reported to have poor human oral bioavailability, supporting low absorption for the similarly polar 5-azacytidine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Uridine, a pyrimidine ribonucleoside, has oral bioavailability of about 7% in humans; 5-azacytidine is a pyrimidine ribonucleoside that is deaminated to a 5-azauridine-like species, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Levovirin, a highly polar nucleoside, has less than 10% oral bioavailability due to very low permeability, illustrating that polar nucleosides can be poorly absorbed, though L-stereochemistry limits direct transferability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Fludarabine, a nucleoside analogue, has 50–65% oral bioavailability, providing contradictory evidence that some nucleoside analogues are well absorbed, but its purine/arabinose structure is less transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C35"],
      "claim": "Clofarabine, another nucleoside analogue, has about 57.5% oral bioavailability, contradictory to a low prediction but with limited transferability due to its purine base and 2'-halogen modification.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) for 5-azacytidine based on the poor absorption of closely related polar pyrimidine nucleosides (uridine, NHC) and its susceptibility to deamination and chemical instability; confidence is moderate because some nucleoside analogues such as fludarabine and clofarabine are well absorbed.",
  "evidence_gaps": [
    "The highest-similarity record (Molecule 1) has a SMILES/record mismatch: the SMILES corresponds to cytidine while the records describe cladribine, so it was not used as reliable evidence.",
    "No direct experimental oral bioavailability value for azacitidine itself is present in the provided evidence.",
    "Transferability from purine nucleoside analogues (fludarabine, clofarabine) is limited by differences in base structure and sugar stereochemistry."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

